def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Sort and remove duplicates
    unique_sorted = sorted(set(nums))

    if not unique_sorted:
        return ""

    result = []
    start = unique_sorted[0]
    end = unique_sorted[0]

    for i in range(1, len(unique_sorted)):
        if unique_sorted[i] == end + 1:
            # Consecutive number, extend the current range
            end = unique_sorted[i]
        else:
            # Non-consecutive number, finalize the previous range
            if start == end:
                result.append(str(start))
            elif end - start >= 2:
                result.append(f"{start}..{end}")
            else:
                result.append(str(start))
                result.append(str(end))
            # Start a new range
            start = unique_sorted[i]
            end = unique_sorted[i]

    # Handle the last range
    if start == end:
        result.append(str(start))
    elif end - start >= 2:
        result.append(f"{start}..{end}")
    else:
        result.append(str(start))
        result.append(str(end))

    return ",".join(result)
